```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <cstdlib>
using namespace std;

int main() {
    ifstream plik("ciag.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);
    int n = tab.size();

    int maxDiff = abs(tab[1] - tab[0]), maxPos = 0;
    int minDiff = abs(tab[1] - tab[0]), minPos = 0;
    for (int i = 1; i < n - 1; i++) {
        int diff = abs(tab[i + 1] - tab[i]);
        if (diff > maxDiff) { maxDiff = diff; maxPos = i; }
        if (diff < minDiff) { minDiff = diff; minPos = i; }
    }
    cout << "a) Max roznica sasiadow: |" << tab[maxPos] << " - " << tab[maxPos + 1]
         << "| = " << maxDiff << ", pozycje: " << maxPos + 1 << "-" << maxPos + 2 << endl;
    cout << "b) Min roznica sasiadow: |" << tab[minPos] << " - " << tab[minPos + 1]
         << "| = " << minDiff << ", pozycje: " << minPos + 1 << "-" << minPos + 2 << endl;
    return 0;
}
```

**Wyjasnienie**: Skan liniowy po parach sasiadow. Obliczamy wartosc bezwzgledna roznicy i sledzac min/max zapamietujemy pozycje.

